using System;using System.Diagnostics;using System.Drawing;using System.IO;using System.Windows.Forms;using UCSPyayStudentRegistration.Helpers;using UCSPyayStudentRegistration.Queries;
namespace UCSPyayStudentRegistration.Forms {
 public class FrmStudentInformation:StyledForm{} public class FrmParentInformation:StyledForm{} public class FrmAcademicInformation:StyledForm{} public class FrmDocuments:StyledForm{} public class FrmPayment:StyledForm{} public class FrmReview:StyledForm{}
 public class FrmDocumentVerification:StyledForm { int applicationId;DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,SelectionMode=DataGridViewSelectionMode.FullRowSelect,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.DisplayedCells};public FrmDocumentVerification():this(0){}public FrmDocumentVerification(int id){applicationId=id;Text="Document Verification";Size=new Size(950,560);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(10)};var open=UiTheme.Secondary("Open File");bar.Controls.Add(open);foreach(string s in new[]{"Verified","Invalid","Needs Correction"}){string status=s;var b=new Button{Text=status,Width=135,Height=36};b.Click+=delegate{UpdateStatus(status);};bar.Controls.Add(b);}Controls.Add(g);Controls.Add(bar);Controls.Add(UiTheme.Heading("Document Verification","Open each file, record its result, and add a clear admin note"));open.Click+=delegate{if(g.CurrentRow==null)return;string path=Convert.ToString(g.CurrentRow.Cells["FilePath"].Value);if(File.Exists(path))Process.Start(path);else MessageBox.Show("The uploaded file could not be found.");};LoadData();}void UpdateStatus(string status){if(g.CurrentRow==null)return;string note=Microsoft.VisualBasic.Interaction.InputBox("Admin note (required for invalid/correction):",status,"");if(status!="Verified"&&string.IsNullOrWhiteSpace(note)){MessageBox.Show("Enter an admin note.");return;}new DocumentQuery().Verify(Convert.ToInt32(g.CurrentRow.Cells["DocumentId"].Value),status,note);LoadData();}void LoadData(){g.DataSource=new DocumentQuery().ForApplication(applicationId);if(g.Columns.Contains("FilePath"))g.Columns["FilePath"].Visible=false;if(g.Columns.Contains("DocumentId"))g.Columns["DocumentId"].Visible=false;}}
 public class FrmPaymentManagement:StyledForm { int applicationId;DataGridView g=new DataGridView{Dock=DockStyle.Fill,ReadOnly=true,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill};public FrmPaymentManagement():this(0){}public FrmPaymentManagement(int id){applicationId=id;Text="Payment Verification";Size=new Size(920,470);var bar=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=60,Padding=new Padding(10)};foreach(string s in new[]{"Verified","Invalid","Needs Correction"}){string status=s;var b=new Button{Text=status,Width=145,Height=36};b.Click+=delegate{if(MessageBox.Show("Set payment status to "+status+"?","Confirm",MessageBoxButtons.YesNo)==DialogResult.Yes){new PaymentQuery().Verify(applicationId,status);LoadData();}};bar.Controls.Add(b);}Controls.Add(g);Controls.Add(bar);Controls.Add(UiTheme.Heading("Payment Verification","Compare the required fee, paid amount, transaction ID and receipt"));LoadData();}void LoadData(){g.DataSource=new PaymentQuery().ForApplication(applicationId);if(g.Columns.Contains("PaymentId"))g.Columns["PaymentId"].Visible=false;}}
}
